function updateIntelligenceUI(){
 if(!payload||$('intelligence-panel').hidden)return;
 const live=payload.snapshot.cars.find(c=>c.id===selected),shown=tape.active?viewingCars?.find(c=>c.id===selected):live,q=shown?.intelligence;
 $('intelligence-driver').textContent=(live?.name??'')+' · '+(tape.active?'ภาพบันทึก':'แผนการแข่งขัน');
 if(!q){$('intelligence-action').textContent='กำลังอ่านสถานการณ์';return;}
 const actions={DRAFT:'เก็บความเร็วในลมดูด',BRAKE_DUEL:'เตรียมดวลเบรก',ABORT_ATTACK:'ช่องหรือระยะไม่พอ ถอนแผน',EXIT_SETUP:'จัดรถเพื่อสวนขาออก',EXIT_TARGET:'เร่งสวนขาออก',HOLD_SPACE:'ขึ้นคู่ รักษาพื้นที่',DEFEND:'ป้องกันทางที่เลือก',FEINT:'หลอกไลน์ อ่านการตอบสนอง',OUTSIDE_SWITCH:'สลับออกนอกหลังคู่แข่งปิดใน',PASS_COMMIT:'รักษาทางแซง',COUNTER:'เตรียมไล่เอาคืน'};
 $('intelligence-action').textContent=actions[q.action]??'เลือกไลน์และความเร็วตามสถานการณ์';
 const plan=q.plan;$('intelligence-horizon').textContent=plan?'มองต่อไป T'+plan.turns.map(t=>t.number).join(' → T')+(plan.rival?' · คู่แข่งคัน '+plan.rival:' · ถนนโล่ง'):'รอข้อมูลสนาม';
 const body=$('intelligence-options');body.replaceChildren();for(const c of plan?.candidates??[]){const row=document.createElement('tr');if(c.kind===(q.commit?.kind??plan.selected))row.className='selected-plan';for(const text of [c.label,c.rejected??c.time.toFixed(1)+' s',Math.round(c.exitKPH)+' km/h']){const td=document.createElement('td');td.textContent=text;row.append(td);}body.append(row);}
 const e=q.resources;$('intelligence-energy').textContent=e?'พลังงาน '+Math.round(e.fraction*100)+'% · '+e.reason:'';
 const m=plan?.learned;$('intelligence-memory').textContent=m?.observedCorners?'อ่านคู่แข่ง '+m.observedCorners+' โค้ง · ใช้ไลน์ใน '+Math.round(m.insideRate*100)+'%'+(m.brakingSamples?' · จุดเริ่มเบรกเฉลี่ย '+Math.round(m.brakingDistance)+' ม. ก่อนโค้ง':''):'กำลังเก็บพฤติกรรมคู่แข่ง';
}

