function drawRain(now){if(!payload||now-lastRain<66)return;lastRain=now;const canvas=$('rain-layer'),ctx=canvas.getContext('2d'),rain=renderer?.cpu?(payload.weather?.rain??0):0;ctx.clearRect(0,0,390,780);if(rain>.03){ctx.strokeStyle='#bed2df';ctx.lineWidth=1;ctx.beginPath();const t=running?payload.time:payload.time;for(let i=0;i<Math.round(rain*70);i++){const x=(i*137.7+t*37)%420,y=(i*91.3+t*510)%810;ctx.moveTo(x,y);ctx.lineTo(x-5,y+18);}ctx.stroke();}const wet=Math.min(1,(payload.weather?.water??0)/2);if(renderer.cpu){if(!scene.background?.isColor)scene.background=new T.Color();scene.background.setHex(night22.night?(rain>.3?0x172036:finish44.profile.nightSky):(rain>.3?0x8198a4:0xa9c9d6));}scene.fog.color.setHex(night22.night?(rain>.3?0x1c2b40:finish44.profile.nightFog):(rain>.3?0x8d9c9f:finish44.profile.dayFog));const road=scenery.roadMaterial;if(road){road.color.setScalar(1-wet*.2);road.roughness=.94-wet*.44;}}

