function applyQuality(mode,persist=true){
 if(!['AUTO','LOW','HIGH'].includes(mode))return;
 qualityMode=mode;renderPolicy.setMode(mode);if(!renderer){$('quality-mode').value=mode;if(persist)try{localStorage.setItem('F1M-QUALITY',mode);}catch{}return;}const profile=renderPolicy.profile(renderer.cpu);renderer.shadowMap.enabled=profile.shadows;
 const size=profile.shadowSize;if(sun.shadow.mapSize.x!==size){sun.shadow.mapSize.set(size,size);sun.shadow.map?.dispose();sun.shadow.map=null;}
 for(const model of models.values())model.detailed=false;
 $('quality-mode').value=mode;$('quality-quick').textContent='ภาพ '+({AUTO:'ออโต้',LOW:'ประหยัด',HIGH:'สูง'}[mode]);
 if(persist)try{localStorage.setItem('F1M-QUALITY',mode);}catch{}
 dirty=true;resize();
}
